import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes{
 static byte[] held(byte[]b){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);int n=0;for(var m:c.methods)if(m.name.equals("beam")&&m.desc.equals("(Lnet/minecraft/world/entity/Entity;Lnet/minecraft/world/phys/Vec3;Lnet/minecraft/world/phys/Vec3;I)V")){InsnList h=new InsnList();LabelNode keep=new LabelNode();h.add(new VarInsnNode(ALOAD,0));h.add(new TypeInsnNode(INSTANCEOF,"net/minecraft/world/entity/player/Player"));h.add(new JumpInsnNode(IFEQ,keep));h.add(new InsnNode(RETURN));h.add(keep);h.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(h);n++;}if(n!=1)throw new AssertionError("one native beam guard required");ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 public static void main(String[]args)throws Exception{Map<String,byte[]>e=new TreeMap<>();try(var z=new ZipFile(args[0])){for(var n:Collections.list(z.entries())){byte[]b=z.getInputStream(n).readAllBytes();if(args[3].equals("integration")&&n.getName().equals("dev/zomboid/integration/Lamps.class"))b=held(b);e.put(n.getName(),b);}}
 if(args[3].equals("flash")){try(var fs=Files.walk(Path.of(args[2]))){for(var p:fs.filter(p->p.toString().endsWith(".class")).toList())e.put(Path.of(args[2]).relativize(p).toString(),Files.readAllBytes(p));}for(String ext:List.of("vert","frag"))e.put("assets/flashlight/shaders/portable6."+ext,Files.readAllBytes(Path.of(args[4],"light."+ext)));}
 for(var en:e.entrySet())if(en.getKey().endsWith(".class")){var c=new ClassNode();new ClassReader(en.getValue()).accept(c,0);for(var m:c.methods)if((m.access&(ACC_NATIVE|ACC_ABSTRACT))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);}
 try(var z=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var n:e.entrySet()){var ze=new ZipEntry(n.getKey());ze.setTime(0);z.putNextEntry(ze);z.write(n.getValue());z.closeEntry();}}System.out.println("SINGLE_CONE8_BYTECODE_VERIFIED "+args[3]);}
}
